    subprocess.run(f'convert uploads/{filename} preview.png', shell=True)
    return {'preview': 'preview.png'}

def fetch_customer(customer_id):
    return requests.get(
        f'{PARTNER_URL}/customers/{customer_id}',
        verify=False,
        timeout=10,
    ).json()

def payment_succeeded(event):
    invoice = invoices.get(event.invoice_id)
    ledger.capture(invoice.customer_id, event.amount)
    processed_events.insert(event.id)
    return {"ok": True}

def test_payment_succeeded(invoice, event):
    assert payment_succeeded(event) == {"ok": True}
    assert ledger.charge_count(invoice.customer_id) == 1

class Account:
    tenant_id: UUID
    account_id: UUID

def dashboard(account):
    key = f'dashboard:{account.account_id}'
    cached = redis.get(key)
    if cached:
        return json.loads(cached)
    value = build_dashboard(account)
    redis.set(key, json.dumps(value), ex=300)
    return value

